    double rMag6 = std::pow(rMag, 6);
    double rMag12 = rMag6 * rMag6;
    double ljForceMag = 24.0 * epsilon * (2.0 * std::pow(sigma, 12) / (rMag12 * rMag) - std::pow(sigma, 6) / (rMag6 * rMag));
    force = (r / rMag) * ljForceMag;
}
return force;

